import csv, json, platform
from pathlib import Path
p=Path(__file__).resolve().parent
records=json.loads((p/'out/measurements.json').read_text())
lines=['# ДЗ 2 «Сканер документов» — отчёт', '', '**Дата проверки:** 28.10.2026. **Автор и группа:** не указаны.', '', '**Статус:** программная часть реализована и проверена. Ниже фактические измерения на пяти синтетических кадрах курса, а не на собственных фотографиях. Для полной сдачи отсутствуют 18 собственных снимков с разметкой, запись с веб-камеры и файлы L3 `text-lamp.png` / `text-gt.png`.', '', '## 1. Числа', '', 'Все исходные JSON-ответы и команды: [measurements.json](out/measurements.json), [commands.sh](out/commands.sh). Время зависит от машины и нагрузки.']
def table(head, rows):
    lines.append('')
    lines.append('| '+' | '.join(head)+' |')
    lines.append('| '+' | '.join(['---']*len(head))+' |')
    for row in rows: lines.append('| '+' | '.join(str(x) for x in row)+' |')
    lines.append('')
def subset(command):
    return [r for r in records if r['result'].get('command')==command]
lines+=['', '### 1.1. Шум', '', 'Команды `noise sample_data/<кадр>.jpg`, рабочее разрешение 640 × 480.']
noise=subset('noise')
table(['Файл','σ шума'],[(r['command_line'].split()[3],r['result']['noise_sigma']) for r in noise if 'added_sigma' not in r['result']])
lines+=['Проверка на `sample_data/desk.jpg`: `noise … --add-sigma 5|10|25`.']
table(['Добавлено σ','Оценка','σ фильтра','Остаток измеренный','Остаток по формуле'],[tuple(r['result'][k] for k in ('added_sigma','noise_sigma_noisy','filter_sigma','noise_after_measured','noise_after_predicted')) for r in noise if 'added_sigma' in r['result']])
lines+=['### 1.2. Края', '', 'Для каждого кадра выполнены `edges` по умолчанию, с `--close 0`, с `--canny 50,150`.']
table(['Кадр','Настройка','Медиана','Пороги','Краёв, %','Отрезков Хафа'],[(r['command_line'].split()[3], 'без закрытия' if '--close 0' in r['command_line'] else '50,150' if '--canny' in r['command_line'] else 'медиана', r['result'].get('median'),r['result']['canny'],r['result']['edge_pct'],r['result']['segments']) for r in subset('edges')])
lines+=['### 1.3. IoU и устойчивость', '', '`eval sample_data --ann sample_data/corners.json --seeds 20`. На негативном кадре прочерк означает отсутствие эталонного четырёхугольника, а успех — правильный отказ.']
for label in ('default','fixed','noclose'):
    rows=list(csv.DictReader((p/f'out/eval_{label}.csv').open()))
    lines += [f'**Настройка `{label}`**: '+{'default':'медианные пороги','fixed':'`--canny 50,150`','noclose':'`--close 0`'}[label]+'.']
    table(['Кадр','contour IoU','hough IoU','hough успехов/20','auto IoU','Путь auto','мс contour / hough / auto'],[(r['file'],r['contour_iou'] or '—',r['hough_iou'] or '—',r['hough_ok_of_20'],r['auto_iou'] or '—',r['auto_path'] or 'нет', ' / '.join(r[m+'_ms'] for m in ('contour','hough','auto'))) for r in rows])
lines += ['Сверка с `sample_data/README.md`: значения σ шума, доли краёв, IoU и успехов RANSAC совпали с эталонными в указанных допусках. Время обработки отличается и зависит от окружения.', '', 'Сводки для трёх настроек (найдено из 4 / средний IoU по 4 позитивным / отклонено из 1 / среднее время в мс):']
for r in subset('eval'):
    lines += ['```json',json.dumps(r['result'],ensure_ascii=False,indent=2),'```']
lines+=['### 1.4. Бинаризация', '', 'Команды `scan sample_data/<кадр>.jpg --canny 50,150 --binarize <метод> --gt sample_data/page-gt.png`. Число — совпадение чернил с эталоном, %. Файлы: `out/<кадр>_otsu.png`, `out/<кадр>_adaptive.png`, `out/<кадр>_flat.png`.']
scans=subset('scan')
table(['Кадр','Otsu','Adaptive','Flat'],[(name,*[next(r['result']['ink_match_pct'] for r in scans if f'/{name}.jpg' in r['command_line'] and r['result']['binarize']==m) for m in ('otsu','adaptive','flat')]) for name in ('desk','corner','tiles','plain')])
lines+=['На `corner.jpg` присутствуют затенение и закрытый угол; значения включают ошибку геометрии и ресемплинга. Они не заменяют отдельный эксперимент L3 с попиксельно совпадающим эталоном.', '', '### 1.5. Видео', '', f'Платформа: `{platform.platform()}`, архитектура `{platform.machine()}`. Источник: файл курса `sample_data/clip.mp4`, 640 × 480; камера не использовалась. Вход содержит 60 кадров, лист присутствует в первых 45. FPS измерен при обработке файла и не является измерением FPS камеры. Для auto включена запись `out/video.mp4` (20 кадров/с, 3 секунды).']
table(['Режим','Кадров','FPS','С листом, %','Медиана detect, мс'],[(r['command_line'].split('--method ')[1].split()[0],*[r['result'][k] for k in ('frames','fps','found_pct','detect_ms_median')]) for r in subset('video')])
lines+=['## 2. Три вопроса', '', '**2.1. Контуры или Хаф + RANSAC?**', '', 'Контурный путь требует замкнутой границы: на `desk.jpg` он находит лист, а на `corner.jpg` кружка разрушает подходящий четырёхугольный контур. Хаф + RANSAC восстанавливает закрытый угол пересечением продолжений видимых сторон. На `tiles.jpg` длинные швы создают конкурирующие прямые: устойчивость RANSAC нужно оценивать по 20 зёрнам, а не по одному удачному запуску. Контуры здесь полезны как первый этап `auto`; на `desk.jpg` их преимущество — меньшее время, а у Хафа — точность углов. Эти примеры не дают двух независимых случаев выигрыша каждого пути на собственных снимках: этот пункт нужно дополнить собственным набором.', '', '![Края desk](out/desk_edges_default.png)', '![Края corner](out/corner_edges_default.png)', '![Края tiles](out/tiles_edges_fixed.png)', '', '**2.2. Почему правило медианы может ошибаться?**', '', 'Медиана описывает абсолютную яркость, тогда как Canny проверяет перепад яркости. У светлого кадра `plain.jpg` медианные пороги слишком велики: карта краёв пустая и оба пути теряют лист. Фиксированная пара 50/150 возвращает границу, но добавляет посторонние линии на плитке. Для применения выбран `--method auto --canny 50,150`: контуры проверяются первыми и дополняются Хафом. Сравнение по четырём позитивным примерам приведено в таблицах; вывод о пятнадцати собственных фотографиях пока сделать нельзя. Альтернатива для дальнейшего исследования — пороги по распределению модуля градиента, после оценки шума.', '', '**2.3. Шум и закрытие текста.**', '', 'Оценка шума использует медиану абсолютного отклика ядра; деление на 0.6745 переводит медиану модуля гауссовской величины в σ, деление на 6 компенсирует норму ядра. Значения для разных сцен и добавок 5, 10, 25 приведены в §1.1; сравнивать их как собственные измерения дневного и искусственного освещения нельзя. При большом шуме σ фильтра ограничена сверху значением 3, поэтому требуемый остаток в один код недостижим. Измеренный остаток сравнивается с дискретной формулой σ·√Σh²; не с повторной оценкой шума по уже коррелированному изображению. Закрытие текста сокращает долю внутренних краёв и отрезков Хафа (см. §1.2), позволяя RANSAC выбирать стороны страницы, а не строки текста.', '', '## 3. Негативные кадры и отказы', '', 'В доступном наборе только один негативный кадр — `nosheet.jpg`. Результат каждой настройки находится в CSV (`*_found`); проверка яркости внутри кандидата и снаружи помогает отклонить книгу. Это эвристика, поэтому светлая книга или монитор всё ещё могут вызвать ложное срабатывание. Позитивный отказ по умолчанию — `plain.jpg`: причина в порогах Canny, исправление на этом примере — 50/150. Ещё два обязательных негативных кадра и разбор трёх собственных негативов отсутствуют.', '', '## 4. Настройка', '', '```text', '--method auto --canny 50,150', '```', '', 'В `eval` аргумент `--method` не нужен: эта команда проверяет все три режима. Реализация `auto_canny` и медианный режим по умолчанию сохранены для воспроизводимости исходного сравнения.', '', '## 5. Воспроизведение и оставшиеся действия', '', '```bash', 'python -m pip install -r requirements.txt', 'python -m pytest tests -q', 'python reproduce.py', '```', '', 'Все отдельные команды записаны в `out/commands.sh`. Результат самопроверки — `out/tests.txt`; CI скопирован из шаблона, но удалённый запуск GitHub Actions не выполнялся.', '', 'Для полного отчёта нужны собственные `data/01.jpg` … `data/18.jpg` по условиям задания, разметка и замеры:', '', '```bash', 'python docscan.py annotate data/*.jpg --ann data/corners.json', 'python docscan.py eval data --ann data/corners.json --seeds 20 --csv out/eval.csv --overlays out/eval', 'python docscan.py eval data --ann data/corners.json --seeds 20 --canny 50,150 --csv out/eval_fixed_own.csv', 'python docscan.py video --source 0 --method auto --seconds 10 --save out/video_camera.mp4', '```', '', 'Также повторить видеозамер для contour и hough, указать модель процессора и разрешение камеры; выполнить опыт L3 после добавления файлов. Не заменять отсутствующие собственные фотографии кадрами курса.', '', '## 6. Инструменты', '', 'Код 13 функций, скрипт повторения экспериментов и текст отчёта подготовлены с помощью OpenAI Codex. CLI, тесты, вспомогательные функции и синтетические примеры взяты из выданного шаблона курса. Использованы NumPy и OpenCV; RANSAC, порядок углов, отбор четырёхугольника и IoU реализованы явно. Фактические версии окружения сохранены в `out/environment.txt`. Перед показом следует разобраться в каждой функции; основные формулы и ограничения описаны в docstring.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n')

# Сведения о пользовательской раскладке сохраняются при пересборке.
if (p / "data" / "manifest.json").exists():
    with (p / "REPORT.md").open("a") as report:
        report.write('\n\n## Обновление: раскладка пользовательских фотографий\n\nПо просьбе пользователя папка `data/` заполнена файлами `01.jpg`–`18.jpg` из 10 присланных фотографий (8 повторов). Соответствие позиций и исходников: [data/README.md](data/README.md), машинный список: `data/manifest.json`.\n\nФото `16.jpg` подходит как негатив с ноутбуком. Остальные позиции заполнены заглушками без видимого листа; название категории не описывает фактическое содержимое. Разметка всех 18 файлов — `null`. Эта раскладка не добавляет позитивных наблюдений и не изменяет приведённые выше результаты на примерах курса. Ранее сгенерированное изображение в набор не включено.\n')
